"""Offline ADB and length-prefixed plist (usbmuxd sync) exchange parsing.

Every helper here is offline: payloads are decoded from campaign evidence or
rendered as base64 probe certificates.  Nothing is ever transmitted.

Wire rules implemented (PROTOCOL.md, "Causal application census"):

* ADB open payload -- exactly one packet: six little endian uint32 fields
  ``(command, arg0, arg1, length, checksum, magic)`` followed by exactly
  ``length`` body bytes (no trailing data).  ``length <= 65535``, the checksum
  is the sum of the body bytes modulo 2**32, ``command ^ magic == 0xffffffff``
  and the command is CNXN or AUTH.  A CNXN body is strict UTF-8 and its
  signature is ``(CNXN, version, banner)`` with the version taken from arg0
  bits 16-23, 8-15 and 0-7; arg1 is irrelevant.  An AUTH signature is
  ``(AUTH, arg0, arg1, body_bytes)`` without any text decoding.
* sync open payload -- exactly two consecutive frames, each a 4 byte big
  endian body length in 1..65532 followed by that many bytes, without trailing
  data.  Each body is parsed with ``plistlib.loads`` and must be a dictionary
  with exactly ``Key``, ``Request`` and ``Value`` where ``Request`` is
  ``GetValue`` and ``Value`` a nonempty string; the first Key is
  ``ProductVersion`` and the second ``ProductName``.

Signatures are only ever compared for equality, so equivalent normalisations
of the same semantic content compare equal while different content does not.
"""
import base64
import io
import plistlib
import struct

CNXN = 0x4e584e43
AUTH = 0x48545541
CLSE = 0x45534c43
MAGIC_MASK = 0xffffffff
ADB_HEADER = 24
ADB_MAX_BODY = 65535
SYNC_HEADER = 4
SYNC_MAX_BODY = 65532
CONNECT_ARGUMENTS = (0x01000000, 4096)
CONNECT_IDENTITY = b'host::zgrab2'
SYNC_LABEL = 'usbmuxd'
SYNC_PROTOCOL = '2'
SYNC_REQUEST = 'GetValue'
GET_VERSION = 0
GET_PRODUCT_NAME = 1
USBMUXD_COMMANDS = {
    GET_VERSION: ('ProductVersion', SYNC_REQUEST),
    GET_PRODUCT_NAME: ('ProductName', SYNC_REQUEST)}


class WireError(ValueError):
    """Raised for any malformed device payload."""


def checksum(data):
    """ADB packet checksum: sum of body bytes modulo 2**32."""
    return sum(data) & MAGIC_MASK


def packet(command, arg0, arg1, body):
    """Render one ADB packet with the length/checksum/magic encoding."""
    return struct.pack('<6I', command, arg0, arg1, len(body), checksum(body),
                       command ^ MAGIC_MASK) + body


def send_connect():
    """Outbound ADB CNXN probe packet."""
    arg0, arg1 = CONNECT_ARGUMENTS
    return packet(CNXN, arg0, arg1, CONNECT_IDENTITY)


def send_close():
    """Outbound ADB CLSE packet with zeroed arguments and an empty body."""
    return packet(CLSE, 0, 0, b'')


def read_adb_response(data):
    """Parse exactly one ADB packet; reject framing, checksum and command errors."""
    size = len(data)
    if size < ADB_HEADER:
        raise WireError('short ADB header')
    command, arg0, arg1, length, check, magic = struct.unpack('<6I', data[:ADB_HEADER])
    if command ^ magic != MAGIC_MASK:
        raise WireError('bad ADB magic')
    if command != CNXN and command != AUTH:
        raise WireError('unsupported ADB command')
    if length > ADB_MAX_BODY:
        raise WireError('oversized ADB body')
    if size != ADB_HEADER + length:
        raise WireError('ADB body length mismatch')
    body = data[ADB_HEADER:]
    if check != checksum(body):
        raise WireError('bad ADB checksum')
    if command == CNXN:
        banner = body.decode('utf-8')
        return ('CNXN', (arg0 >> 16) & 255, (arg0 >> 8) & 255, arg0 & 255, banner)
    return ('AUTH', arg0, arg1, body)


def get_value_request(kind):
    """Render one length-prefixed usbmuxd GetValue request frame."""
    key, request = USBMUXD_COMMANDS[kind]
    body = plistlib.dumps({'Key': key, 'Label': SYNC_LABEL,
                           'ProtocolVersion': SYNC_PROTOCOL, 'Request': request},
                          fmt=plistlib.FMT_XML, sort_keys=False)
    return struct.pack('>I', len(body)) + body


def read_sync_frame(stream):
    """Read one length-prefixed plist frame and parse it with plistlib."""
    header = stream.read(SYNC_HEADER)
    if len(header) != SYNC_HEADER:
        raise WireError('truncated sync frame header')
    size = struct.unpack('>I', header)[0]
    if size < 1 or size > SYNC_MAX_BODY:
        raise WireError('invalid sync frame length')
    body = stream.read(size)
    if len(body) != size:
        raise WireError('truncated sync frame body')
    return plistlib.loads(body)


def sync_value(value, key):
    """Validate a parsed GetValue response dictionary and return its Value."""
    if type(value) is not dict or set(value) != {'Key', 'Request', 'Value'}:
        raise WireError('invalid sync response shape')
    if value['Key'] != key or value['Request'] != SYNC_REQUEST:
        raise WireError('invalid sync response keys')
    text = value['Value']
    if type(text) is not str or not text:
        raise WireError('invalid sync response value')
    return text


def get_plists(stream, kind):
    """Legacy helper: read one frame and validate it for ``kind``."""
    return sync_value(read_sync_frame(stream), USBMUXD_COMMANDS[kind][0])


def send_messages(data):
    """Parse a sync open payload: ProductVersion frame then ProductName frame."""
    stream = io.BytesIO(data)
    version = sync_value(read_sync_frame(stream), 'ProductVersion')
    product = sync_value(read_sync_frame(stream), 'ProductName')
    if stream.read(1):
        raise WireError('trailing sync frame data')
    return ('sync', version, product)


def signature(kind, data):
    """Parsed open signature for ``kind``, or None for malformed wire data."""
    try:
        if kind == 'tcp':
            if data:
                return None
            return ('tcp',)
        if kind == 'adb':
            return read_adb_response(data)
        if kind == 'sync':
            return send_messages(data)
    except Exception:
        # Bad framing, checksums, plists, text decoding or recursion are all
        # "malformed open wire data": the row stays valid, the state is unknown.
        return None
    return None


def probe_script(kind):
    """Base64 outbound probe certificate (send, finish) for a service kind."""
    encode = lambda payload: base64.b64encode(payload).decode('ascii')
    if kind == 'tcp':
        return [], []
    if kind == 'adb':
        return [encode(send_connect())], [encode(send_close())]
    return ([encode(get_value_request(GET_VERSION)),
             encode(get_value_request(GET_PRODUCT_NAME))], [])


CERTIFICATES = {kind: probe_script(kind) for kind in ('tcp', 'adb', 'sync')}
